// O(n^2) time, O(1) space: no extra memory, slow
boolean hasPairBrute(int[] a, int target) {
    for (int i = 0; i < a.length; i++)
        for (int j = i + 1; j < a.length; j++)
            if (a[i] + a[j] == target) return true;
    return false;
}

// O(n) time, O(n) space: HashSet trades memory for speed
boolean hasPairFast(int[] a, int target) {
    Set<Integer> seen = new HashSet<>();   // O(n) extra space
    for (int x : a) {
        if (seen.contains(target - x)) return true;
        seen.add(x);
    }
    return false;
}

// Recursion: O(n) TIME and O(n) STACK SPACE (n frames deep)
int sum(int[] a, int i) { return i == a.length ? 0 : a[i] + sum(a, i + 1); }
```

