int linearSearch(int[] a, int target) {
    for (int i = 0; i < a.length; i++)
        if (a[i] == target) return i;   // best: hit at i=0 (1 step)
    return -1;                           // worst: absent (n steps)
}

// Best case:    target == a[0]        -> O(1)
// Worst case:   target absent / last  -> O(n)
// Average case: target somewhere mid   -> ~n/2 = O(n)

// Quicksort: average O(n log n), worst O(n^2) on a bad pivot choice
