for (int k = n; k >= 1; k /= 2) doWork();   // n=16 -> 16,8,4,2,1 = 5 steps

// Binary search: O(log n) - each step discards half the range
int bsearch(int[] a, int target) {
    int lo = 0, hi = a.length - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == target) return mid;
        else if (a[mid] < target) lo = mid + 1;  // drop left half
        else hi = mid - 1;                        // drop right half
    }
    return -1;
}
// 1,000,000 elements -> about 20 comparisons
```

