// O(1) space: one accumulator, in-place pointers
int sum(int[] a) {
    int total = 0;                 // single variable
    for (int x : a) total += x;
    return total;
}
void reverseInPlace(int[] a) {
    int i = 0, j = a.length - 1;   // two pointers - constant space
    while (i < j) { int t = a[i]; a[i++] = a[j]; a[j--] = t; }
}

// O(n) space: allocates a structure that grows with n
int[] reverseCopy(int[] a) {
    int[] out = new int[a.length];           // grows with n -> O(n)
    for (int i = 0; i < a.length; i++) out[i] = a[a.length - 1 - i];
    return out;
}
